INSERT INTO `broadcast_text` (`ID`,`Text`,`Text1`,`LanguageID`,`ConditionID`,`EmotesID`,`Flags`,`ChatBubbleDurationMs`,`VoiceOverPriorityID`,`SoundKitID1`,`SoundKitID2`,`EmoteID1`,`EmoteID2`,`EmoteID3`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`VerifiedBuild`) VALUES
(324570,'Excellent. Go to the font where arcane magic is at its strongest. In the absence of proper Highborne sorcerers walking the world freely once more it is your best bet of having the energy required to cleanse the globe after it has rotted for so long.\r\n\r\nI have nearly finished poring over the tome you brought me to finish the blade once you have it. Perhaps there is hope yet that we may witness this masterwork in its intended form.','',0,0,0,256,0,4,0,0,1,1,0,0,1000,0,70959);
